-- name: store.update_change
-- mode: write
-- scope: catalog
-- tables: tv_changes*
UPDATE tv_changes SET updated_at = $2, anchor_at = CASE WHEN $3 THEN $4 ELSE anchor_at END, approved_at = CASE WHEN $5 THEN $6 ELSE approved_at END, approved_by = CASE WHEN $7 THEN $8 ELSE approved_by END, auto_rule = CASE WHEN $9 THEN $10 ELSE auto_rule END, base_release_id = CASE WHEN $11 THEN $12 ELSE base_release_id END, change_set = CASE WHEN $13 THEN $14 ELSE change_set END, created_by = CASE WHEN $15 THEN $16 ELSE created_by END, diff = CASE WHEN $17 THEN $18 ELSE diff END, digest = CASE WHEN $19 THEN $20 ELSE digest END, end_reason = CASE WHEN $21 THEN $22 ELSE end_reason END, ended_at = CASE WHEN $23 THEN $24 ELSE ended_at END, kinds = CASE WHEN $25 THEN $26 ELSE kinds END, origin = CASE WHEN $27 THEN $28 ELSE origin END, ready_at = CASE WHEN $29 THEN $30 ELSE ready_at END, release_id = CASE WHEN $31 THEN $32 ELSE release_id END, source = CASE WHEN $33 THEN $34 ELSE source END, staged_at = CASE WHEN $35 THEN $36 ELSE staged_at END, state = CASE WHEN $37 THEN $38 ELSE state END, superseded_by = CASE WHEN $39 THEN $40 ELSE superseded_by END, swap_at = CASE WHEN $41 THEN $42 ELSE swap_at END, swap_wait = CASE WHEN $43 THEN $44 ELSE swap_wait END, swapped_at = CASE WHEN $45 THEN $46 ELSE swapped_at END, title = CASE WHEN $47 THEN $48 ELSE title END, verify_report = CASE WHEN $49 THEN $50 ELSE verify_report END WHERE id = $1
